template <bool Is64Aware = false>
class FlatBufferBuilderImpl {
 public:
  typedef typename std::conditional<Is64Aware, uoffset64_t, uoffset_t>::type SizeT;
  explicit FlatBufferBuilderImpl(
      size_t initial_size = 1024, Allocator* allocator = nullptr,
      bool own_allocator = false,
      size_t buffer_minalign = AlignOf<largest_scalar_t>())
      : buf_(initial_size, allocator, own_allocator, buffer_minalign,
             static_cast<SizeT>(Is64Aware ? FLATBUFFERS_MAX_64_BUFFER_SIZE
                                          : FLATBUFFERS_MAX_BUFFER_SIZE)),
        num_field_loc(0),
        max_voffset_(0),
        length_of_64_bit_region_(0),
        nested(false),
        finished(false),
        minalign_(1),
        force_defaults_(false),
        dedup_vtables_(true),
        string_pool(nullptr) {
    EndianCheck();
  }
  FlatBufferBuilderImpl(FlatBufferBuilderImpl&& other) noexcept
      : buf_(1024, nullptr, false, AlignOf<largest_scalar_t>(),
             static_cast<SizeT>(Is64Aware ? FLATBUFFERS_MAX_64_BUFFER_SIZE
                                          : FLATBUFFERS_MAX_BUFFER_SIZE)),
        num_field_loc(0),
        max_voffset_(0),
        length_of_64_bit_region_(0),
        nested(false),
        finished(false),
        minalign_(1),
        force_defaults_(false),
        dedup_vtables_(true),
        string_pool(nullptr) {
    EndianCheck();
    Swap(other);
  }
  FlatBufferBuilderImpl& operator=(FlatBufferBuilderImpl&& other) noexcept {
    FlatBufferBuilderImpl temp(std::move(other));
    Swap(temp);
    return *this;
  }
  void Swap(FlatBufferBuilderImpl& other) { /* ... body omitted for brevity ... */ }
  ~FlatBufferBuilderImpl() { if (string_pool) delete string_pool; }
  void Reset() { Clear(); buf_.reset(); }
  void Clear() { /* ... */ }
  SizeT GetSize() const { return buf_.size(); }
  template <bool is_64 = Is64Aware>
  typename std::enable_if<is_64, uoffset_t>::type GetSizeRelative32BitRegion() const { /* ... */ }
  template <bool is_64 = Is64Aware>
  typename std::enable_if<!is_64, uoffset_t>::type GetSizeRelative32BitRegion() const { return static_cast<uoffset_t>(GetSize()); }
  uint8_t* GetBufferPointer() const { Finished(); return buf_.data(); }
  flatbuffers::span<uint8_t> GetBufferSpan() const { Finished(); return flatbuffers::span<uint8_t>(buf_.data(), buf_.size()); }
  uint8_t* GetCurrentBufferPointer() const { return buf_.data(); }
  DetachedBuffer Release() { Finished(); DetachedBuffer buffer = buf_.release(); Clear(); return buffer; }
  uint8_t* ReleaseRaw(size_t& size, size_t& offset) { Finished(); uint8_t* raw = buf_.release_raw(size, offset); Clear(); return raw; }
  size_t GetBufferMinAlignment() const { Finished(); return minalign_; }
  void Finished() const { FLATBUFFERS_ASSERT(finished); }
  void ForceDefaults(bool fd) { force_defaults_ = fd; }
  void DedupVtables(bool dedup) { dedup_vtables_ = dedup; }
  void Pad(size_t num_bytes) { buf_.fill(num_bytes); }
  void TrackMinAlign(size_t elem_size) { if (elem_size > minalign_) minalign_ = elem_size; }
  void Align(size_t elem_size) { TrackMinAlign(elem_size); buf_.fill(PaddingBytes(buf_.size(), elem_size)); }
  void PushFlatBuffer(const uint8_t* bytes, size_t size) { PushBytes(bytes, size); finished = true; }
  void PushBytes(const uint8_t* bytes, size_t size) { buf_.push(bytes, size); }
  void PopBytes(size_t amount) { buf_.pop(amount); }
  template <typename T> void AssertScalarT() { static_assert(flatbuffers::is_scalar<T>::value, "T must be a scalar type"); }
  template <typename T, typename ReturnT = uoffset_t>
  ReturnT PushElement(T element) { /* ... */ }
  template <typename T, template <typename> class OffsetT = Offset>
  uoffset_t PushElement(OffsetT<T> off) { return PushElement(ReferTo(off.o)); }
  void TrackField(voffset_t field, uoffset_t off) { /* ... */ }
  template <typename T> void AddElement(voffset_t field, T e, T def) { /* ... */ }
  template <typename T> void AddElement(voffset_t field, T e) { /* ... */ }
  template <typename T> void AddOffset(voffset_t field, Offset<T> off) { /* ... */ }
