  void AddStructOffset(voffset_t field, uoffset_t off) { TrackField(field, off); }
  uoffset_t ReferTo(uoffset_t off) { Align(sizeof(uoffset_t)); return ReferTo(off, GetSizeRelative32BitRegion()); }
  uoffset64_t ReferTo(uoffset64_t off) { Align(sizeof(uoffset64_t)); return ReferTo(off, GetSize()); }
