namespace flatbuffers {

class Registry {
 public:
  void Register(const char* file_identifier, const char* schema_path) {
    Schema schema;
    schema.path_ = schema_path;
    schemas_[file_identifier] = schema;
  }

  bool FlatBufferToText(const uint8_t* flatbuf, size_t len, std::string* dest) {
    if (len < sizeof(uoffset_t) + kFileIdentifierLength) {
      lasterror_ = "buffer truncated";
      return false;
    }
    std::string ident(
        reinterpret_cast<const char*>(flatbuf) + sizeof(uoffset_t),
        kFileIdentifierLength);
    Parser parser;
    if (!LoadSchema(ident, &parser)) return false;
    auto err = GenText(parser, flatbuf, dest);
    if (err) {
      lasterror_ =
          "unable to generate text for FlatBuffer binary: " + std::string(err);
      return false;
    }
    return true;
  }

  DetachedBuffer TextToFlatBuffer(const char* text,
                                  const char* file_identifier) {
    Parser parser;
    if (!LoadSchema(file_identifier, &parser)) return DetachedBuffer();
    if (!parser.Parse(text)) {
      lasterror_ = parser.error_;
      return DetachedBuffer();
    }
    return parser.builder_.Release();
  }

  void SetOptions(const IDLOptions& opts) { opts_ = opts; }

  void AddIncludeDirectory(const char* path) { include_paths_.push_back(path); }

  const std::string& GetLastError() { return lasterror_; }

 private:
  bool LoadSchema(const std::string& ident, Parser* parser) {
    auto it = schemas_.find(ident);
    if (it == schemas_.end()) {
      lasterror_ = "identifier for this buffer not in the registry";
      return false;
    }
    auto& schema = it->second;
    std::string schematext;
    if (!LoadFile(schema.path_.c_str(), false, &schematext)) {
      lasterror_ = "could not load schema: " + schema.path_;
      return false;
    }
    parser->opts = opts_;
    if (!parser->Parse(schematext.c_str(), include_paths_.data(),
                       schema.path_.c_str())) {
      lasterror_ = parser->error_;
      return false;
    }
    return true;
  }

  struct Schema {
    std::string path_;
  };

  std::string lasterror_;
  IDLOptions opts_;
  std::vector<const char*> include_paths_;
  std::map<std::string, Schema> schemas_;
};

